def test_dedupe_sessions_keeps_last_record_and_sorts_by_day_then_id():
    earlier = {"id": "a", "day": 9, "converted": True}
    later = {"id": "a", "day": 2, "converted": False}
    same_day = {"id": "b", "day": 2, "converted": True}
    first_day = {"id": "z", "day": 1, "converted": None}
